INSERT OR IGNORE INTO evidence(id,claim_id,source_id,source_location,catalogue_number,evidence_type,direction,strength,research_notes)
SELECT 'evidence.'||substr(c.id,7),c.id,
 CASE WHEN c.id LIKE 'claim.v0180.karaijin_%' OR c.id LIKE 'claim.v0180.raijin_%' THEN 'source.japanese.raijin.kokugakuin'
      WHEN c.id LIKE 'claim.v0180.fragment_%' THEN 'source.japanese.kamo_genealogy.kokugakuin'
      WHEN c.id LIKE 'claim.v0180.festival_%' THEN 'source.japanese.kamo_festival.official'
      WHEN c.id IN ('claim.v0180.korin_copy_sotatsu') THEN 'source.japan.korin_wind_thunder.colbase'
      WHEN c.id LIKE 'claim.v0180.korin_%' THEN 'source.japan.korin_wind_thunder.tnm'
      ELSE 'source.japanese.raijin_screen.kyohaku' END,
 'Authority record and scoped summary',NULL,
 CASE WHEN c.knowledge_layer='TEXTUAL_WITNESS' THEN 'MANUSCRIPT' WHEN c.knowledge_layer='RITUAL_PRACTICE' THEN 'OFFICIAL_SITE' ELSE 'MODERN_SCHOLARSHIP' END,
 'SUPPORTS',c.confidence,'v0.18 evidence; modern image reception and living public practice remain distinct'
FROM claims c WHERE c.id LIKE 'claim.v0180.%';

